local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local UIModule = CS.Engine.UI.UIModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)

---@class WorldBossDetailsService
local WorldBossDetailsService = Class("WorldBossDetailsService")

function WorldBossDetailsService.new(facade)
    local obj = WorldBossDetailsService.New()
    obj.facade = facade

    return obj
end

function WorldBossDetailsService:UpdateInfo()
    CfUtils.FillImage(self.facade.Bg, self.facade.worldBossPlanModelProxy:ModelId())
    CfUtils.FillText(self.facade.TxtName, self.facade.worldBossModelProxy:Name())
    SetButtonAction(self.facade.Btncheck, Bind(self, self.OnClick))
    self:UpdateTimeDownInfo()
end

function WorldBossDetailsService:UpdateTimeDownInfo()
    if not isNull(self.CoTimeDown) then
        CDTimerModule.GetInstance():RemoveCD(self.CoTimeDown)
        self.CoTimeDown = nil
    end

    self.CoTimeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local remainTime = worldBossComponent:GetRemainTime()
        local durTime = worldBossComponent:GetBossDurationTime()
        local isOpen = worldBossComponent:IsOpen()
        local desc = ""
        if isOpen then
            desc = localize("离封锁关闭时间")..CfUtils.GetTimeHMS2(checkNumber(durTime) - math.abs(remainTime))
        else
            desc = localize("离封锁开启时间")..CfUtils.GetTimeHMS2(math.abs(remainTime))
        end
        CfUtils.FillText(self.facade.TextTime, desc)
    end, CountDownTime, false, true)
end

function WorldBossDetailsService:OnClick()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
    self.CoClick = cs_coroutine.start(function()
        UIModule.OpenDialog({
            id = Constants.UITypeIds.UIWorldBossDetailsDialog
        }, {
            { id = Constants.UITypeIds.UIWorldBossMainDialog }
        })
    end)
    self.CoClick = nil
end

function WorldBossDetailsService:Dispose()
    if self.CoClick then
        cs_coroutine.stop(self.CoClick)
        self.CoClick = nil
    end
    if not isNull(self.CoTimeDown) then
        CDTimerModule.GetInstance():RemoveCD(self.CoTimeDown)
        self.CoTimeDown = nil
    end
end

return WorldBossDetailsService